import 'package:crypto_keys/crypto_keys.dart';
import 'dart:typed_data';

void main() {
  var keyPair = KeyPair.generateSymmetric(128);
  var encrypter = keyPair.publicKey.createEncrypter(algorithms.encryption.aes.gcm);
  var content = Uint8List.fromList('Secret'.codeUnits);
  var encrypted = encrypter.encrypt(content);
  var decrypter = keyPair.privateKey.createEncrypter(algorithms.encryption.aes.gcm);
  var decrypted = decrypter.decrypt(encrypted);
  print(String.fromCharCodes(decrypted));
}

import 'dart:io';
import 'package:pdfrx_engine/pdfrx_engine.dart';

void main() async {
  await pdfrxInitialize();

  final document = await PdfDocument.openFile('test.pdf');
  try {
    if (document.pages.isEmpty) return;
    final page = document.pages.first;
    final pageImage = await page.render(
      width: (page.width * 200 / 72).round(),
      height: (page.height * 200 / 72).round(),
    );
    if (pageImage == null) return;
    try {
      final image = pageImage.createImageNF();
      await File('output.png').writeAsBytes(img.encodePng(image));
    } finally {
      pageImage.dispose();
    }
  } finally {
    await document.dispose();
  }
}

