      if (!db.objectStoreNames.contains('users')) {
        db.createObjectStore('users', autoIncrement: true);
      }
    },
  );
  final txn = db.transaction('users', idbModeReadWrite);
  final store = txn.objectStore('users');
  await store.add({'name': 'Alice'});
  await txn.completed;
}

