void main() {
  final key = randomBytes(32);
  final nonce = randomBytes(12);
  final aad = toUtf8('order-id=INV-1001');
  final plain = toUtf8('Ship 3 units to dock-7');

  final aes = AES(key).gcm(nonce, aad: aad);
